// Shared by "3 Write" and "7 Chat" (build.mjs puts it at the top of their Code nodes).
// Turns a draft (headline, script, callout_label, chart_title, chart_kind, blurb, reports_used) into the
// render spec, builds the chart from the story itself, and lists every problem the guard finds
// (must-work row 9). A number may come from the story or from a news report the draft says it used.
// `ctx` is the run's client (name, look, style card) and its recent reports.
// "3-1-1" is a name, not three numbers.
const numbersIn = (text) => (String(text).replace(/\b3-1-1\b/g, " ").match(/\d[\d,]*(?:\.\d+)?/g) || []).map((m) => Number(m.replace(/,/g, "")));

// Where each allowed number comes from, most specific place first. The trace shows these.
function numberOrigins(story, used = []) {
  const origin = new Map();
  const note = (n, where) => { if (!origin.has(n)) origin.set(n, where); };
  note(7, "the window: 7 days"); note(8, "the window: 8 weeks"); note(9, "the window: 9 weeks");
  for (const [k, v] of Object.entries(story)) if (typeof v === "number") { note(v, `story ${k}`); note(Math.abs(v), `story ${k}`); }
  for (const a of story.by_area || []) note(a.count, `story by_area, ${a.area}`);
  for (const x of story.weekly || []) note(x.count, `story weekly, week ending ${x.week_ending}`);
  for (const n of numbersIn(JSON.stringify(story))) note(n, "story");
  for (const r of used) for (const n of numbersIn(`${r.title} ${r.summary}`)) note(n, `report ${r.id}, ${r.source}`);
  return origin;
}

function unknownNumbers(story, fields, used = []) {
  const origin = numberOrigins(story, used);
  const unknown = [];
  for (const [field, text] of Object.entries(fields)) {
    for (const n of numbersIn(text)) if (!origin.has(n)) unknown.push(`${n} in ${field}`);
  }
  return unknown;
}

function buildSpec(story, d, ctx = {}) {
  const client = ctx.client || {};
  const ids = Array.isArray(d.reports_used) ? d.reports_used.map(String) : [];
  const used = (ctx.reports || []).filter((r) => ids.includes(r.id));
  const hasAreas = (story.by_area || []).length > 0;
  const chartKind = story.chart_kind === "series" ? "series" : d.chart_kind === "weekly" || !hasAreas ? "weekly" : d.chart_kind === "by_area" ? "by_area" : story.chart_kind;
  // A drop shows its percentage; anything else its ratio, or the plain count when there is no history.
  const callout = {
    value: story.kind === "series" ? `${story.latest_value}${story.unit || ""}`
      : story.direction === "down" ? `${Math.abs(story.pct_change)}%` : story.ratio ? `${story.ratio}×` : String(story.this_week),
    label: d.callout_label,
  };
  // How the chart looks, which an editor can change from the thread: bar, line or pie; one item in
  // the accent colour; and the accent colour itself (a hex value), else the client's own.
  const style = ["bar", "line", "pie"].includes(d.chart_style) ? d.chart_style : "bar";
  const color = /^#[0-9a-f]{6}$/i.test(String(d.accent_color || "")) ? d.accent_color : null;
  const spec = {
    headline: d.headline,
    script: d.script,
    callout,
    chart: {
      kind: style,
      order: chartKind === "weekly" || chartKind === "series" ? "time" : "value",
      highlight: d.highlight || null,
      title: d.chart_title,
      data: chartKind === "series"
        ? story.points.map((p) => ({ label: p.label, value: p.value }))
        : chartKind === "weekly"
        ? story.weekly.slice(-6).map((w) => ({ label: new Date(w.week_ending + "T12:00:00Z").toLocaleDateString("en-CA", { month: "short", day: "numeric", timeZone: "UTC" }), value: w.count }))
        : story.by_area.slice(0, 6).map((a) => ({ label: a.area, value: a.count })),
      source_note: [story.source_note, ...new Set(used.map((r) => r.source))].join("; "),
    },
    brand: { name: client.name || "", desk: client.look?.desk || "", accent: color || client.look?.accent || null },
    duration_s: 20,
  };
  // Scenes, a closing line and per-label colours, which the editor can change from the thread.
  const SCENES = ["intro", "chart", "close"];
  const scenes = Array.isArray(d.scenes) ? d.scenes.filter((x) => SCENES.includes(x)) : [];
  spec.scenes = scenes.length ? [...new Set(scenes)] : SCENES;
  spec.closing_line = String(d.closing_line || "").trim();
  const labels = new Set(spec.chart.data.map((x) => x.label));
  const colors = Object.fromEntries(Object.entries(d.bar_colors && typeof d.bar_colors === "object" ? d.bar_colors : {})
    .filter(([k, v]) => labels.has(k) && /^#[0-9a-f]{6}$/i.test(String(v))));
  spec.chart.colors = Object.keys(colors).length ? colors : null;
  const fields = { headline: d.headline, script: d.script, callout_value: callout.value, callout_label: d.callout_label, chart_title: d.chart_title, blurb: d.blurb, closing_line: spec.closing_line };
  const origin = numberOrigins(story, used);
  const number_checks = [];
  for (const [field, text] of Object.entries(fields)) {
    for (const n of numbersIn(text)) number_checks.push({ field, number: n, from: origin.get(n) || null });
  }
  if (spec.chart.highlight && !spec.chart.data.some((x) => x.label === spec.chart.highlight)) spec.chart.highlight = null;
  const problems = [];
  const unknown = number_checks.filter((c) => !c.from).map((c) => `${c.number} in ${c.field}`);
  if (unknown.length) problems.push(`${unknown.join(", ")} is not in the story or a report it uses`);
  const words = String(d.script).trim().split(/\s+/).length;
  // Any length the editor wants, up to about 45 seconds of narration.
  const lo = 15;
  const hi = 115;
  if (words < lo || words > hi) problems.push(`the script is ${words} words; it needs ${lo} to ${hi}`);
  return { spec, chart_kind: chartKind, words, problems, used, number_checks };
}

// The draft as the model sees it, rebuilt from a run.
const draftOf = (run) => ({
  headline: run.spec.headline,
  script: run.spec.script,
  callout_label: run.spec.callout.label,
  chart_title: run.spec.chart.title,
  chart_kind: run.chart_kind || run.story.chart_kind,
  blurb: run.blurb,
  reports_used: (run.reports_used || []).map((r) => r.id),
  chart_style: run.spec.chart.kind || "bar",
  highlight: run.spec.chart.highlight || null,
  accent_color: run.spec.brand?.accent && run.spec.brand.accent !== run.client?.look?.accent ? run.spec.brand.accent : null,
  bar_colors: run.spec.chart.colors || null,
  scenes: run.spec.scenes || ["intro", "chart", "close"],
  closing_line: run.spec.closing_line || "",
});

// Shared by the "7 Chat" Code nodes (build.mjs puts it at the top of each): the Slack messages the bot
// posts, and the row it keeps for each review thread in the "editor_threads" data table.
const EDITOR = "C0CHNAKERA9";
const OUTLET = "C0CHVG02PJM";

const section = (text) => ({ type: "section", text: { type: "mrkdwn", text: String(text).slice(0, 2900) } });
const context = (text) => ({ type: "context", elements: [{ type: "mrkdwn", text: String(text).slice(0, 2900) }] });
const button = (text, action, style) => ({ type: "button", text: { type: "plain_text", text }, action_id: `newsroom_${action}`, value: action, ...(style ? { style } : {}) });

function numbersLine(story) {
  const change = story.direction === "up"
    ? `${story.ratio}× the usual level`
    : `down ${Math.abs(story.pct_change)}% from the usual level`;
  return `${story.this_week} ${story.unit} in the week ${story.week_start} to ${story.week_ending}, against an average of ${story.avg_prev_8_weeks} a week over the 8 weeks before (${change}).`;
}

// For a story asked for in Slack: every page the web search cited, with the exact words it was cited
// for, so the editor can check the script against the source before approving.
function webSourceBlocks(run) {
  const web = (run.reports || []).filter((r) => r.feed === "web");
  const ws = run.web_search;
  if (!ws) return [];
  const used = new Set((run.reports_used || []).map((r) => r.id));
  const searched = ws.queries?.length ? `Searched for: ${ws.queries.map((q) => `"${q}"`).join(", ")}.` : "";
  if (!web.length) {
    return [section(`*Web sources to check*\n${ws.error ? `The web search failed: ${ws.error}` : "The web search found nothing to cite."} ${searched}`.trim())];
  }
  const clip = (t, n) => (t.length > n ? t.slice(0, n).replace(/\s+\S*$/, "") + "..." : t);
  return [
    section(`*Web sources to check* (${web.length}; ${web.filter((r) => used.has(r.id)).length} used in the script)\n${searched}`),
    ...web.map((r) => section(
      `${used.has(r.id) ? "*Used in the script.* " : ""}<${r.url}|${r.title}> (${r.source}${r.page_age ? `, ${r.page_age}` : ""})\n>_${clip(r.summary || "", 400)}_`,
    )),
  ];
}

function scriptBlocks(run) {
  const s = run.story;
  const spec = run.spec;
  const areas = (s.by_area || []).slice(0, 6).map((a) => `${a.area} ${a.count}`).join(", ");
  const weeks = (s.weekly || []).slice(-6).map((w) => w.count).join(", ");
  const chart = spec.chart.data.map((d) => `${d.label} ${d.value}`).join(", ");
  return [
    section(`*${spec.headline}*`),
    section(`*Script* (${run.script_words || String(spec.script).split(/\s+/).length} words)\n>${spec.script}`),
    section(
      `*The data*\n• ${s.dataset}: ${s.type}\n• ${numbersLine(s)}` +
        (areas ? `\n• This week by neighbourhood: ${areas}` : "") +
        (weeks ? `\n• Last 6 weeks: ${weeks}` : "") +
        `\n• Source: <${s.source_url}|${s.source_note}>`,
    ),
    ...((run.reports_used || []).filter((r) => r.feed !== "web").length
      ? [section(`*Context from the news*\n${run.reports_used.filter((r) => r.feed !== "web").map((r) => `• ${r.url ? `<${r.url}|${r.title}>` : r.title} (${r.source})`).join("\n")}`)]
      : []),
    ...webSourceBlocks(run),
    section(`*On screen*\n• Big number: ${spec.callout.value}, "${spec.callout.label}"\n• Chart: ${spec.chart.title} (${spec.chart.kind || "bar"} chart${spec.chart.highlight ? `, ${spec.chart.highlight} highlighted` : ""}${spec.brand?.accent ? `, colour ${spec.brand.accent}` : ""})\n• Values: ${chart}`),
    ...(spec.closing_line ? [section(`*Closing scene*\n${spec.closing_line}`)] : []),
    section(`*Newsletter blurb*\n${run.blurb}`),
  ];
}

const scriptButtons = () => ({ type: "actions", elements: [button("Approve script", "approve_script", "primary"), button("Reject", "reject", "danger")] });
const videoButtons = () => ({ type: "actions", elements: [button("Approve and publish", "approve_video", "primary"), button("Reject", "reject", "danger")] });
const HOW_TO_REPLY = "Reply in this thread to change anything: the script, headline, big number label, blurb, or the chart (bar, line or pie, a colour, which item stands out). After the video is made, a change remakes it in about 20 seconds. Every number has to come from the data or a news report the script cites.";

// The run without the parts that are large or only for this message.
function keep(run) {
  const { audio_base64, chat, route, working_note, claude_body, post, row, render, ...rest } = run;
  return rest;
}
const rowFor = (threadTs, stage, run, history) => ({ thread_ts: threadTs || "", stage, state: JSON.stringify({ run: keep(run), history: (history || []).slice(-12) }) });

// What every branch hands to "Reply ready": the Slack message to post and the row to save.
const reply = (threadTs, text, blocks, stage, run, history) => ({
  json: {
    post: { channel: EDITOR, ...(threadTs ? { thread_ts: threadTs } : {}), text: String(text).slice(0, 3000), ...(blocks ? { blocks } : {}), unfurl_links: false },
    row: rowFor(threadTs, stage, run, history),
  },
});

// "Start review": the first message of a review thread, posted to the editor channel after Write.
// It shows the headline, script, the numbers behind them and what goes on screen, before any voice
// or video is made. Its timestamp becomes the thread the editor replies in. A draft someone asked
// for in Slack goes into the thread under their request instead.
const run = $input.first().json;
if (!run.spec || !run.story) throw new Error("Start review needs a run from 3 Write, with story and spec.");
const threadTs = run.request?.ts || "";
const intro = run.request
  ? `*Here is a draft for <@${run.request.user}>'s request.* Nothing is recorded or published until it is approved.`
  : "*New story for review.* Nothing is recorded or published until you approve.";
const blocks = [
  section(intro),
  ...scriptBlocks(run),
  ...(run.trace_url ? [context(`<${run.trace_url}|Open the run trace>: every source, the ranking, the news offered, what Claude was asked and answered, where each number came from, and the cost.${run.ledger_url ? ` <${run.ledger_url}|Run ledger>: every run and what it cost.` : ""}`)] : []),
  context(HOW_TO_REPLY),
  scriptButtons(),
];
return [reply(threadTs, `For review: ${run.spec.headline}`, blocks, "script", run, [])];

